// 用来存放登录相关请求
import Request from '@/utils/requests'

// 获取图形验证码
export const getPicCodeAjax = () => {
  return Request({
    url: '/captcha/image',
    method: 'GET'
  })
}

// 获取短信验证码
export const getMessageCodeAjax = (captchaCode, captchaKey, mobile) => {
  return Request({
    url: '/captcha/sendSmsCaptcha',
    method: 'POST',
    data: {
      form: {
        captchaCode,
        captchaKey,
        mobile
      }
    }
  })
}

export const loginAjax = (mobile, smsCode) => {
  return Request({
    url: '/passport/login',
    method: 'POST', // method单词不要写错了！
    data: { // body参数的名字为data，而不是body，传递query参数为params
      form: {
        mobile,
        smsCode,
        isParty: false,
        partyData: {}
      }
    },
    headers: {
      platform: 'H5'
    }
  })
}
