<template>
  <div class="box">
    <van-nav-bar title="会员登录" left-text="返回" left-arrow @click-left="onClickLeft" />
    <!-- 也可以使用插槽来定制 -->
    <!-- <van-nav-bar title="会员登录" @click-left="onClickLeft">
      <template #left>
        <van-icon name="arrow-left" size="18" color="black"/><span>返回</span>
      </template>
</van-nav-bar> -->
    <div class="content">
      <h1>手机号登录</h1>
      <span class="tip">未注册的手机号登录后将自动注册</span>
      <div class="form-content">
        <input placeholder="请输入手机号码" v-model="phoneNumber">
        <hr>
        <div style="display:flex">
          <input placeholder="请输入图形验证码" v-model="picCode">
          <!-- 这里v-if避免出现图片碎裂的效果，有图片再显示 -->
          <img :src="picUrl" v-if="picUrl" @click="getPicCode">
        </div>
        <hr>
        <input placeholder="请输入短信验证码" v-model="messageCode" maxlength="6">
        <button @click="getMessageCode">{{ currentSecond === 60 ? '获取验证码' : ('重新发送(' + currentSecond + ')秒') }}</button>
        <hr>
      </div>
    </div>
    <div class="button">
      <van-button type="primary" round size="large" color="#F89E20" @click="login">登录</van-button>
    </div>
  </div>
</template>

<script>
import { getPicCodeAjax, getMessageCodeAjax, loginAjax } from '@/api/login'
import { mapMutations } from 'vuex'

export default {
  name: 'LoginIndex',
  data () {
    return {
      picKey: '', // 将来请求传递的图形验证码唯一标识
      picUrl: '', // 人机校验图片url（base64）
      totalSecond: 60,
      currentSecond: 60,
      intervalID: null,
      picCode: 'abcd', // 用户输入的图形验证码
      // phoneNumber: '15751776629',
      phoneNumber: '15115553217',
      messageCode: '246810' // 用户输入的短信验证码
    }
  },
  methods: {
    ...mapMutations('user', ['setUserInfo']),
    onClickLeft () {
      // this.$router.push('/home')
      this.$router.go(-1)
    },
    // 封装为一个函数是因为点击图片还要更换图片
    async getPicCode () {
      const response = await getPicCodeAjax()
      // console.log(response)
      this.picUrl = response.data.base64 // 存储图片
      this.picKey = response.data.key // 存储key
      this.$toast('获取图形验证码成功')
    },
    validFn () {
      // 校验用户输入的手机号，正则表达式来自于网上资源
      if (!/^(13[0-9]|14[01456879]|15[0-35-9]|16[2567]|17[0-8]|18[0-9]|19[0-35-9])\d{8}$/.test(this.phoneNumber)) {
        this.$toast.fail('请输入正确的手机号')
        return false
      }
      // 校验验证码
      if (!/^\w{4}$/.test(this.picCode)) {
        this.$toast.fail('请输入正确的图形验证码')
        return false
      }
      return true
    },
    async getMessageCode () {
      // 校验通过在进行后面的流程
      if (!this.validFn()) {
        return
      }

      // 只有定时器为空，且两个second都为60时才开启
      if (!this.intervalID && this.totalSecond === this.currentSecond) {
        // 预期：希望如果响应的status非200，最好抛出一个promise错误，await只会等待成功的promise
        const response = await getMessageCodeAjax(this.picCode, this.picKey, this.phoneNumber)
        console.log(response)
        this.$toast.success('短信发送成功，请注意查收')
        // 添加下面这一行是为了从60秒开始倒计时，不然点击后总要先顿一下
        this.currentSecond--
        this.intervalID = setInterval(() => {
          this.currentSecond = this.currentSecond - 1
          // console.log(this.currentSecond)
          if (this.currentSecond <= 0) {
            clearInterval(this.intervalID)
            this.currentSecond = 60
            this.intervalID = null
          }
        }, 1000)
      }
    },
    async login () {
      if (!this.validFn()) {
        return
      }
      if (!/^\d{6}$/.test(this.messageCode)) {
        this.$toast.fail('请输入6位数手机验证码')
        return
      }
      const response = await loginAjax(this.phoneNumber, this.messageCode)
      // console.log(response.data)
      this.setUserInfo(response.data)
      this.$toast.success('登陆成功')
      // this.$router.push('/home')
      this.$router.go(-1)
    }
  },
  created () {
    this.getPicCode()
  },
  // 离开页面需要清除，不然离开页面了，定时器还在消耗性能，遇到类似问题需要敏感点
  destroyed () {
    clearInterval(this.intervalID)
  }
}
</script>

<style scoped lang="less">
.content {
  margin: 70px 30px 0px;

  .tip {
    color: #C7C5C5;
  }

  .form-content {
    padding: 80px 0px;

    input {
      border: 0;
      margin: 20px 0px;
    }

    input::placeholder {
      /* 设置提示词的颜色为灰色 */
      color: #C7C5C5;
    }

    img {
      margin: 10px 0 0;
      display: inline-block;
      position: relative;
      height: 35px;
      object-fit: cover;
      /* 保持宽高比，裁剪多余部分 */
    }

    button {
      border: 0;
      background-color: white;
      color: #d69438;
    }
  }

  hr {
    border: none;
    background-color: #f5f5f5;
    height: 2px;
  }
}

.button {
  text-align: center;
  padding: 0px 70px;
}
</style>
